    public static function svg(string $name, string $class = 'w-5 h-5'): string
    {
        $d = self::PATHS[$name] ?? self::PATHS['x-circle'];

        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="%s" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="%s" /></svg>',
            htmlspecialchars($class, ENT_QUOTES, 'UTF-8'),
            $d
        );
    }

    /**
     * SMSGram'ning brend belgisi — qog'oz-samolyot (tezkor yuborish
     * ramzi), ikki qavatli soya bilan. Gradient fonli kvadrat ichida
     * currentColor (odatda oq) rangida ishlatiladi.
     */
    public static function mark(string $class = 'w-4 h-4'): string
    {
        return sprintf(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" class="%s" aria-hidden="true"><path d="M21 3L3 10.5L11 13L21 3Z" /><path d="M21 3L11 13L13.5 21L21 3Z" fill-opacity="0.65" /></svg>',
            htmlspecialchars($class, ENT_QUOTES, 'UTF-8')
        );
    }
